sp_widget.client_script:
api.controller = function($scope, $timeout, $element) {

  /* ============================================================
     CLIENT CONTROLLER — Widget "Simulateur CIMob"

     Le champ doit commencer par un identifiant : on utilise donc
     la forme "api.controller = function(...) { ... };" et non une
     fonction anonyme seule, qui déclenche l'erreur
     "SyntaxError: Expected ident at line 1, column 1".

     Les dépendances ($scope, $timeout, $element) sont injectées
     automatiquement par le Service Portal.

     $element : limite les recherches DOM au widget, pour ne pas
                entrer en conflit avec le reste de la page.
     $timeout : laisse Angular finir son rendu avant de mesurer
                les positions (indispensable pour l'avion).
     ➜ À coller dans le champ "Client controller" du widget.
     ============================================================ */

  var c = this;

  /* ----------------------------------------------------------
     1. ICÔNES SVG
     Tracés embarqués : aucun appel réseau, fonctionne sur
     Intradef. Usage : ICONS.plane
     ---------------------------------------------------------- */
  var ICONS = {
    plane:      '<svg class="icn icn--solid" viewBox="0 0 24 24"><path d="M12 2 L14 9 L21 11.5 L21 13 L14 12 L13.5 18 L16 20 L16 21.5 L12 20.5 L8 21.5 L8 20 L10.5 18 L10 12 L3 13 L3 11.5 L10 9 Z"/></svg>',
    building:   '<svg class="icn" viewBox="0 0 24 24"><path d="M4 21h16M5 21V5a1 1 0 0 1 1-1h8a1 1 0 0 1 1 1v16M15 9h3a1 1 0 0 1 1 1v11M8 7h2M8 11h2M8 15h2"/></svg>',
    earth:      '<svg class="icn" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M3.5 9.5h17M3.5 14.5h17M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18"/></svg>',
    anchor:     '<svg class="icn" viewBox="0 0 24 24"><circle cx="12" cy="5" r="2.5"/><path d="M12 7.5V21M12 21c-4.5 0-8-3-8.5-7M12 21c4.5 0 8-3 8.5-7M9 10h6"/></svg>',
    sun:        '<svg class="icn" viewBox="0 0 24 24"><circle cx="12" cy="12" r="4.5"/><path d="M12 2.5v2.5M12 19v2.5M2.5 12h2.5M19 12h2.5M5 5l1.8 1.8M17.2 17.2 19 19M19 5l-1.8 1.8M6.8 17.2 5 19"/></svg>',
    pin:        '<svg class="icn" viewBox="0 0 24 24"><path d="M12 21s-7-6.2-7-11a7 7 0 0 1 14 0c0 4.8-7 11-7 11Z"/><circle cx="12" cy="10" r="2.5"/></svg>',
    flag:       '<svg class="icn" viewBox="0 0 24 24"><path d="M5 21V4M5 4h13l-2.5 4L18 12H5"/></svg>',
    check:      '<svg class="icn" viewBox="0 0 24 24"><path d="M4.5 12.5 10 18 19.5 7"/></svg>',
    home:       '<svg class="icn" viewBox="0 0 24 24"><path d="M3.5 11 12 3.5 20.5 11M6 9.5V20a.8.8 0 0 0 .8.8h10.4a.8.8 0 0 0 .8-.8V9.5M10 20.5v-6h4v6"/></svg>',
    truck:      '<svg class="icn" viewBox="0 0 24 24"><path d="M2.5 6h11v10h-11zM13.5 9.5H18l3.5 3.5v3h-8"/><circle cx="7" cy="17.5" r="1.8"/><circle cx="17" cy="17.5" r="1.8"/></svg>',
    team:       '<svg class="icn" viewBox="0 0 24 24"><circle cx="9" cy="8.5" r="3"/><path d="M3.5 19.5c0-3 2.5-5 5.5-5s5.5 2 5.5 5"/><circle cx="17" cy="9.5" r="2.3"/><path d="M16.5 14.7c2.3.3 4 2 4 4.3"/></svg>',
    arrowLeft:  '<svg class="icn" viewBox="0 0 24 24"><path d="M20 12H4M10 6l-6 6 6 6"/></svg>',
    refresh:    '<svg class="icn" viewBox="0 0 24 24"><path d="M20 12a8 8 0 1 1-2.3-5.6M20 3.5V8h-4.5"/></svg>'
  };

  /* ----------------------------------------------------------
     2. DONNÉES VENUES DU SERVER SCRIPT
     ---------------------------------------------------------- */
  var SITES  = c.data.sites;
  var THEMES = c.data.themes;
  var STEPS  = c.data.steps;
  var MATRIX = c.data.matrix;

  /* ----------------------------------------------------------
     3. ÉTAT ET UTILITAIRES
     ---------------------------------------------------------- */
  var state = {
    depart: null,
    arrivee: null
  };

  var currentStep = 1;

  /* Recherche limitée au widget grâce à $element */
  function $(selecteur) {
    return $element[0].querySelector(selecteur);
  }

  function $$(selecteur) {
    return $element[0].querySelectorAll(selecteur);
  }

  /* ----------------------------------------------------------
     4. ICÔNES STATIQUES DU TEMPLATE
     Remplit tous les <span data-icn="..."> du HTML.
     ---------------------------------------------------------- */
  function fillStaticIcons() {
    var spans = $$("[data-icn]");
    for (var i = 0; i < spans.length; i++) {
      spans[i].innerHTML = ICONS[spans[i].getAttribute("data-icn")] || "";
    }
  }

  /* ----------------------------------------------------------
     5. STEPPER-TRAJET
     ---------------------------------------------------------- */

  /**
   * Construit les 3 escales et place l'avion sur la ligne.
   * @param {number} etape - 1, 2 ou 3
   */
  function renderRoute(etape) {
    var track = $(".cimob-route__track");

    /* On retire les anciennes escales (ligne et avion restent) */
    var anciennes = track.querySelectorAll(".cimob-route__stop");
    for (var j = 0; j < anciennes.length; j++) {
      anciennes[j].remove();
    }

    STEPS.forEach(function(step, index) {
      var numero = index + 1;

      var el = document.createElement("div");
      el.className = "cimob-route__stop"
                   + (numero === etape ? " is-current" : "")
                   + (numero < etape   ? " is-done"    : "");
      el.innerHTML =
        '<span class="cimob-route__circle" aria-hidden="true">'
        + (numero < etape ? ICONS.check : numero)
        + '</span>'
        + '<span class="cimob-route__label">' + step.label + '</span>';

      track.appendChild(el);
    });

    /* Position de l'avion : toujours SUR la ligne, jamais derrière
       une pastille.
       - étape 1 : juste à droite de la pastille "Départ"
       - étapes 2 et 3 : juste à gauche de la pastille courante

       $timeout laisse Angular terminer son rendu : sans lui, les
       largeurs valent 0 et l'avion se placerait mal. */
    $timeout(function() {
      var pastilles = track.querySelectorAll(".cimob-route__circle");
      var cible = pastilles[etape - 1];
      if (!cible) { return; }

      var rectTrack = track.getBoundingClientRect();
      var rectCible = cible.getBoundingClientRect();

      var ECART = 24; /* distance entre la pastille et l'avion */
      var positionX;

      if (etape === 1) {
        positionX = rectCible.right - rectTrack.left + ECART;
      } else {
        positionX = rectCible.left - rectTrack.left - ECART;
      }

      $(".cimob-plane").style.left = positionX + "px";

      /* La ligne bleue s'arrête juste derrière l'avion */
      $(".cimob-route__done").style.width =
        Math.max(0, positionX - 26 - 14) + "px";
    }, 0);

    /* Titre et sous-titre de l'étape */
    $(".cimob-route__num").textContent = etape;
    $(".cimob-route__title").innerHTML = STEPS[etape - 1].titleHtml;

    var next = $(".cimob-route__next");
    if (etape < STEPS.length) {
      next.style.display = "block";
      next.textContent = "prochaine étape : " + STEPS[etape].titlePlain;
    } else {
      next.style.display = "none";
    }
  }

  /* ----------------------------------------------------------
     6. CARTES DE DESTINATION
     ---------------------------------------------------------- */

  /**
   * Affiche les 6 sites dans une grille.
   * @param {HTMLElement} grid - conteneur .cimob-grid
   * @param {Function} onSelect - appelée avec le site choisi
   */
  function renderSiteCards(grid, onSelect) {
    grid.innerHTML = "";

    SITES.forEach(function(site, index) {
      /* <button> plutôt que <div> pour l'accessibilité clavier */
      var card = document.createElement("button");
      card.type = "button";
      card.className = "cimob-card";
      card.setAttribute("role", "listitem");

      /* La couleur de la zone alimente pastille, anneau et coche */
      card.style.setProperty("--zone", site.color);
      card.style.setProperty("--zone-tint", site.tint);

      /* Apparition en cascade */
      card.style.animationDelay = (index * 60) + "ms";

      card.innerHTML =
        '<span class="cimob-card__check">' + ICONS.check + '</span>'
        + '<span class="cimob-card__icon">' + ICONS[site.icon] + '</span>'
        + '<p class="cimob-card__title">' + site.label + '</p>'
        + '<p class="cimob-card__desc">' + site.desc + '</p>';

      card.addEventListener("click", function() {
        var cartes = grid.querySelectorAll(".cimob-card");
        for (var k = 0; k < cartes.length; k++) {
          cartes[k].classList.remove("is-selected");
        }
        card.classList.add("is-selected");

        /* 320 ms : le temps de voir la coche rebondir */
        $timeout(function() { onSelect(site); }, 320);
      });

      grid.appendChild(card);
    });
  }

  /* ----------------------------------------------------------
     7. NAVIGATION ENTRE ÉTAPES
     ---------------------------------------------------------- */

  /**
   * Affiche l'étape demandée et masque les autres.
   * @param {number} etape - 1, 2 ou 3
   */
  function goToStep(etape) {
    currentStep = etape;

    [1, 2, 3].forEach(function(numero) {
      var section = $("#cimob-step-" + numero);
      section.style.display = (numero === etape) ? "block" : "none";

      /* Rejouer l'animation d'apparition */
      if (numero === etape) {
        section.classList.remove("cimob-step--in");
        void section.offsetWidth;
        section.classList.add("cimob-step--in");
      }
    });

    /* Regénérer les cartes pour rejouer la cascade */
    if (etape === 1) { renderSiteCards($("#cimob-grid-depart"), onSelectDepart); }
    if (etape === 2) { renderSiteCards($("#cimob-grid-arrivee"), onSelectArrivee); }

    renderRoute(etape);
  }

  /* ----------------------------------------------------------
     8. AFFICHAGE DES OFFRES (étape 3)
     ---------------------------------------------------------- */
  function renderResults() {
    var zone = $("#cimob-results");
    var vide = $("#cimob-results-empty");

    zone.innerHTML = "";

    /* Rappel du trajet */
    $(".cimob-result-depart").textContent  = state.depart.label;
    $(".cimob-result-arrivee").textContent = state.arrivee.label;

    /* Lecture de la matrice */
    var parDepart = MATRIX[state.depart.id];
    var offres = parDepart ? parDepart[state.arrivee.id] : null;

    /* Combinaison absente : message d'information */
    if (!offres) {
      vide.style.display = "block";
      return;
    }
    vide.style.display = "none";

    /* Un bloc par thème, en cascade */
    THEMES.forEach(function(theme, index) {
      var items = offres[theme.key] || [];
      if (items.length === 0) { return; }

      var bloc = document.createElement("div");
      bloc.className = "cimob-result-card";
      bloc.style.setProperty("--theme", theme.color);
      bloc.style.setProperty("--theme-tint", theme.tint);
      bloc.style.animationDelay = (index * 150) + "ms";

      var lignes = items.map(function(offre) {
        return '<li>' + ICONS.check + '<span>' + offre + '</span></li>';
      }).join("");

      bloc.innerHTML =
        '<div class="cimob-result-card__header">'
        +   '<span class="cimob-result-card__icon">' + ICONS[theme.icon] + '</span>'
        +   '<p class="cimob-result-card__title">' + theme.titre + '</p>'
        +   '<span class="cimob-result-card__count">'
        +     items.length + ' offre' + (items.length > 1 ? 's' : '')
        +   '</span>'
        + '</div>'
        + '<ul class="cimob-result-card__list">' + lignes + '</ul>';

      zone.appendChild(bloc);
    });
  }

  /* ----------------------------------------------------------
     9. SÉLECTIONS
     ---------------------------------------------------------- */
  function onSelectDepart(site) {
    state.depart = site;
    $(".cimob-summary-depart").textContent = site.label;
    goToStep(2);
  }

  function onSelectArrivee(site) {
    state.arrivee = site;
    renderResults();
    goToStep(3);
  }

  /* ----------------------------------------------------------
     10. MÉTHODES EXPOSÉES AU TEMPLATE
     Appelées depuis le HTML avec ng-click="c.retourDepart()"
     ---------------------------------------------------------- */
  c.retourDepart = function() {
    goToStep(1);
  };

  c.retourArrivee = function() {
    goToStep(2);
  };

  c.recommencer = function() {
    state.depart = null;
    state.arrivee = null;
    goToStep(1);
  };

  /* ----------------------------------------------------------
     11. DÉMARRAGE
     $timeout(0) : on attend que le template soit dans le DOM
     avant de manipuler les éléments.
     ---------------------------------------------------------- */
  $timeout(function() {
    fillStaticIcons();
    goToStep(1);
  }, 0);

  /* L'avion se replace si la fenêtre change de taille */
  window.addEventListener("resize", function() {
    renderRoute(currentStep);
  });

};

sp_widget.css:
/* ============================================================
   CSS — Widget "Simulateur CIMob"
   Cartes blanches arrondies sur fond gris-bleu, pastilles
   d'icônes colorées, marqueur bleu sur les mots-clés.
   Préfixe "cimob-" partout (portage ServiceNow sans collision).
   ➜ À coller dans le champ "CSS" du widget.
   Les variables sont portées par .cimob-container (et non :root)
   pour rester isolées du reste du portail.
   ============================================================ */


/* ------------------------------------------------------------
   VARIABLES
   ------------------------------------------------------------ */
.cimob-container {
  --blue: #000091;          /* bleu France */
  --blue-hover: #1212FF;
  --blue-tint: #F5F5FE;     /* fond bleu très clair */
  --blue-line: #CACAFB;     /* marqueur et bordures claires */
  --blue-soft: #E3E3FD;     /* bordure au survol */

  --text: #161616;
  --text-soft: #666666;

  --page: #F1F2F7;          /* fond de page */
  --card: #FFFFFF;          /* cartes principales */
  --tile: #FAFAFA;          /* cartes internes (sites, offres) */
  --border: #EEEEEE;
  --line: #E0E0EA;

  --radius-card: 20px;
  --radius-tile: 14px;
  --shadow-card: 0 2px 18px rgba(10, 10, 60, 0.06);
  --shadow-soft: 0 4px 16px rgba(10, 10, 60, 0.05);
}


/* ------------------------------------------------------------
   BASE
   ------------------------------------------------------------ */
.cimob-container * {
  box-sizing: border-box;
}

/* Le conteneur porte les variables (voir plus haut) et les styles
   de base. On ne touche pas à <body> : c'est le portail qui gère. */
.cimob-container {
  max-width: 860px;
  margin: 0 auto;
  padding: 24px 16px 40px;
  background: var(--page);
  color: var(--text);
  font-family: "Marianne", "Segoe UI", Roboto, Arial, sans-serif;
  line-height: 1.5;
}

/* Icônes SVG : elles prennent la couleur du texte parent */
.icn {
  width: 1em;
  height: 1em;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
}

/* L'avion est un tracé plein, pas un contour */
.icn--solid {
  fill: currentColor;
  stroke: none;
}

/* Petit intitulé bleu en majuscules, utilisé partout */
.cimob-kicker {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--blue);
  margin: 0 0 10px;
}

/* Le mot surligné au marqueur bleu clair */
.cimob-route__title span {
  color: var(--blue);
  background: linear-gradient(transparent 62%, var(--blue-line) 62%);
  padding: 0 4px;
}


/* ============================================================
   A. STEPPER-TRAJET
   ============================================================ */
.cimob-route {
  background: var(--card);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 32px 32px 24px;
  margin-bottom: 20px;
}

.cimob-route__track {
  position: relative;
  display: flex;
  justify-content: space-between;
  max-width: 480px;
  margin: 0 auto;
}

/* Ligne pointillée grise : le trajet restant */
.cimob-route__track::before {
  content: "";
  position: absolute;
  left: 26px;
  right: 26px;
  top: 25px;
  border-top: 2px dashed var(--line);
}

/* Ligne pointillée bleue : le trajet parcouru (largeur en JS) */
.cimob-route__done {
  position: absolute;
  left: 26px;
  top: 25px;
  width: 0;
  border-top: 2px dashed var(--blue);
  transition: width 0.8s cubic-bezier(0.45, 0, 0.25, 1);
}

/* L'avion vole vers l'escale courante (position en JS) */
.cimob-plane {
  position: absolute;
  top: 11px;
  left: 26px;
  width: 26px;
  height: 26px;
  color: var(--blue);
  transform: translateX(-50%) rotate(90deg);
  transition: left 0.8s cubic-bezier(0.45, 0, 0.25, 1);
  z-index: 2;
  animation: cimob-hover 2.4s ease-in-out infinite;
}

.cimob-plane .icn {
  width: 100%;
  height: 100%;
}

/* Léger flottement, comme en vol */
@keyframes cimob-hover {
  0%, 100% { margin-top: 0; }
  50%      { margin-top: -4px; }
}

/* ---------- Une escale ---------- */
.cimob-route__stop {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  width: 100px;
}

.cimob-route__circle {
  width: 52px;
  height: 52px;
  border-radius: 16px;
  background: var(--tile);
  border: 1px solid var(--border);
  color: #999999;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 15px;
  transition: all 0.4s ease;
}

.cimob-route__circle .icn {
  width: 20px;
  height: 20px;
}

/* Escale en cours : pastille bleue pleine */
.is-current .cimob-route__circle {
  background: var(--blue);
  border-color: var(--blue);
  color: #FFFFFF;
  box-shadow: 0 8px 20px rgba(0, 0, 145, 0.28);
}

/* Escale franchie : pastille bleu clair avec coche */
.is-done .cimob-route__circle {
  background: var(--blue-tint);
  border-color: var(--blue-line);
  color: var(--blue);
}

.cimob-route__label {
  font-size: 13px;
  font-weight: 600;
  color: #999999;
  text-align: center;
  transition: color 0.3s ease;
}

.is-current .cimob-route__label {
  color: var(--blue);
  font-weight: 700;
}

.is-done .cimob-route__label {
  color: var(--text);
}

/* ---------- Titre de l'étape ---------- */
.cimob-route__meta {
  text-align: center;
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid #F0F0F4;
}

.cimob-route__title {
  font-size: 24px;
  font-weight: 700;
  margin: 0;
  color: var(--text);
}

.cimob-route__next {
  font-size: 13px;
  color: var(--text-soft);
  margin: 6px 0 0;
}


/* ============================================================
   B. ÉTAPES (chaque étape est une carte blanche)
   ============================================================ */
.cimob-step {
  background: var(--card);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 28px 26px;
}

/* Classe posée par le contrôleur pour rejouer l'apparition */
.cimob-step--in {
  animation: cimob-rise 0.4s ease both;
}

@keyframes cimob-rise {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}


/* ---------- Cartes de destination ---------- */
.cimob-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}

.cimob-card {
  position: relative;
  background: var(--tile);
  border: 1px solid var(--border);
  border-radius: var(--radius-tile);
  padding: 20px 14px;
  cursor: pointer;
  text-align: center;
  font-family: inherit;
  font-size: inherit;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  /* survol adouci : transition lente et courbe douce */
  transition: transform 0.32s cubic-bezier(0.33, 1, 0.68, 1),
              box-shadow 0.32s cubic-bezier(0.33, 1, 0.68, 1),
              background 0.32s ease,
              border-color 0.32s ease;
  animation: cimob-rise 0.45s cubic-bezier(0.22, 0.7, 0.3, 1) both;
}

/* Survol doux : 2 px de montée, ombre légère, bordure bleutée */
.cimob-card:hover {
  transform: translateY(-2px);
  background: var(--card);
  border-color: var(--blue-soft);
  box-shadow: var(--shadow-soft);
}

/* Sélection : anneau dans la couleur de la zone */
.cimob-card.is-selected {
  background: var(--card);
  border-color: var(--zone);
  box-shadow: 0 0 0 2px var(--zone), var(--shadow-soft);
}

/* Pastille d'icône, couleur injectée par --zone / --zone-tint */
.cimob-card__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  border-radius: 12px;
  background: var(--zone-tint);
  color: var(--zone);
}

.cimob-card__icon .icn {
  width: 22px;
  height: 22px;
}

/* Textes en noir */
.cimob-card__title {
  font-weight: 700;
  font-size: 14px;
  margin: 0;
  color: var(--text);
}

.cimob-card__desc {
  font-size: 12px;
  line-height: 1.4;
  margin: 0;
  color: var(--text);
}

/* Coche de sélection, avec rebond */
.cimob-card__check {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--zone);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transform: scale(0.4);
  transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.cimob-card__check .icn {
  width: 12px;
  height: 12px;
  stroke-width: 2.6;
}

.cimob-card.is-selected .cimob-card__check {
  opacity: 1;
  transform: scale(1);
}


/* ---------- Résumé du trajet (pilule) ---------- */
.cimob-summary {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
  background: var(--blue-tint);
  border-radius: 999px;
  padding: 10px 20px;
  margin: 0 auto 22px;
  width: fit-content;
  font-size: 14px;
  color: var(--text-soft);
}

.cimob-summary strong {
  color: var(--blue);
}

.cimob-summary .icn {
  color: var(--blue);
  width: 16px;
  height: 16px;
}

/* Le petit avion entre les deux sites */
.cimob-mini-plane {
  display: inline-flex;
  color: var(--blue);
  transform: rotate(90deg);
}

.cimob-mini-plane .icn {
  width: 16px;
  height: 16px;
}


/* ============================================================
   C. BLOCS DE RÉSULTATS
   ============================================================ */
.cimob-result-card {
  background: var(--tile);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 20px 22px;
  margin-bottom: 14px;
  animation: cimob-rise 0.5s cubic-bezier(0.22, 0.7, 0.3, 1) both;
}

.cimob-result-card__header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

/* Pastille d'icône du thème */
.cimob-result-card__icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: var(--theme-tint);
  color: var(--theme);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.cimob-result-card__icon .icn {
  width: 22px;
  height: 22px;
}

.cimob-result-card__title {
  font-size: 16px;
  font-weight: 700;
  margin: 0;
  flex: 1;
  color: var(--text);
}

/* Compteur d'offres en pilule */
.cimob-result-card__count {
  font-size: 12px;
  font-weight: 700;
  color: var(--theme);
  background: var(--theme-tint);
  border-radius: 999px;
  padding: 4px 11px;
  white-space: nowrap;
}

.cimob-result-card__list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.cimob-result-card__list li {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 8px 0;
  font-size: 14px;
  line-height: 1.5;
  color: var(--text);
}

.cimob-result-card__list li + li {
  border-top: 1px solid #EFEFEF;
}

.cimob-result-card__list li .icn {
  width: 15px;
  height: 15px;
  color: var(--theme);
  stroke-width: 2.2;
  margin-top: 3px;
}


/* ============================================================
   D. BOUTONS ET ALERTE
   ============================================================ */
.cimob-actions {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 22px;
}

.cimob-btn {
  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  border: none;
  border-radius: 10px;
  padding: 11px 22px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--blue);
  color: #FFFFFF;
  transition: background 0.2s ease, transform 0.2s ease;
}

.cimob-btn:hover {
  background: var(--blue-hover);
  transform: translateY(-2px);
}

.cimob-btn .icn {
  width: 15px;
  height: 15px;
}

/* Bouton secondaire : liseré bleu */
.cimob-btn--secondary {
  background: var(--card);
  color: var(--blue);
  box-shadow: inset 0 0 0 1.5px var(--blue);
}

.cimob-btn--secondary:hover {
  background: var(--blue-tint);
}

/* La flèche avance au survol */
.cimob-btn [data-icn] {
  display: inline-flex;
  transition: transform 0.2s ease;
}

.cimob-btn:hover [data-icn] {
  transform: translateX(4px);
}

/* Alerte "combinaison non renseignée" */
.cimob-alert {
  background: var(--tile);
  border: 1px solid var(--border);
  border-left: 4px solid #0063CB;
  border-radius: var(--radius-tile);
  padding: 20px 22px;
}

.cimob-alert strong {
  display: block;
  margin-bottom: 4px;
  font-size: 16px;
}

.cimob-alert p {
  margin: 0;
  color: var(--text-soft);
  font-size: 14px;
}

/* Accessibilité clavier */
.cimob-card:focus-visible,
.cimob-btn:focus-visible {
  outline: 3px solid var(--blue);
  outline-offset: 3px;
}


/* ============================================================
   E. MOBILE
   ============================================================ */
@media (max-width: 620px) {
  .cimob-container { padding: 24px 14px 60px; }

  .cimob-route { padding: 24px 16px 20px; }
  .cimob-route__circle { width: 44px; height: 44px; }
  .cimob-route__track::before,
  .cimob-route__done { top: 21px; }
  .cimob-plane { top: 8px; width: 22px; height: 22px; }
  .cimob-route__label { font-size: 12px; }
  .cimob-route__title { font-size: 20px; }

  .cimob-step { padding: 20px 16px; }
  .cimob-grid { grid-template-columns: 1fr 1fr; gap: 10px; }
}


/* ============================================================
   F. ACCESSIBILITÉ — couper les animations si demandé (RGAA)
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  .cimob-container *,
  .cimob-container *::before,
  .cimob-container *::after {
    animation: none !important;
    transition: none !important;
  }
}

